const validLocales = [
    'ar-SA',
    'de-DE',
    'en-AU',
    'en-GB',
    'en-US',
    'es-ES',
    'fr-FR',
    'it-IT',
    'pl-PL',
    'pt-BR',
    'pt-PT',
    'zh-CN',
];

const checkLocale = () => {
    if (!process.env.browserLanguage) {
        console.warn('\x1b[33m%s\x1b[0m', 'Warning: browserLanguage parameter missing. Defaulting to en-US');
        process.env.browserLanguage = 'en-US';
    }

    if (!validLocales.includes(process.env.browserLanguage)) {
        console.error(
            `\x1b[31mbrowserLanguage parameter: Incorrect locale information provided '${process.env.browserLanguage}'\x1b[0m`,
        );
        process.exit(1);
    }
};

module.exports = { checkLocale: checkLocale };
